```python
def transform(grid):
    if not grid:
        return []

    # Determine background color (first cell of first row)
    background = grid[0][0]

    # Find the rightmost non-background column in the entire grid
    rightmost_col = -1
    for row in grid:
        for col_idx, val in enumerate(row):
            if val != background:
                rightmost_col = max(rightmost_col, col_idx)

    # If no foreground found, return empty rows
    if rightmost_col == -1:
        return [[background] * len(grid[0]) for _ in grid]

    # Keep only columns up to rightmost_col + 1
    output_width = rightmost_col + 1
    result = []
    for row in grid:
        result.append(row[:output_width])

    return result
